// Get the Groq response
const groqResponse = $input.first().json;

// Extract the JSON string from choices[0].message.content
const contentString = groqResponse.choices[0].message.content;

// Strip markdown fences if present (defensive)
const cleaned = String(contentString)
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// Extract the first JSON object
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
const jsonString = jsonMatch ? jsonMatch[0] : cleaned;

const parsed = JSON.parse(jsonString);

// Validate required fields exist (defensive, in case Groq returns partial)
const requiredFields = ['vendor_name', 'invoice_number', 'amount', 'currency', 'invoice_date', 'due_date', 'line_items_summary'];
const missingFields = requiredFields.filter(f => !(f in parsed));

if (missingFields.length > 0) {
  // Log missing fields but continue — downstream validation handles nulls
  console.log('Missing fields from extraction:', missingFields);
}

return {
  json: {
    vendor_name: parsed.vendor_name || null,
    invoice_number: parsed.invoice_number || null,
    amount: parsed.amount != null ? Number(parsed.amount) : null,
    currency: parsed.currency || null,
    invoice_date: parsed.invoice_date || null,
    due_date: parsed.due_date || null,
    line_items_summary: parsed.line_items_summary || null,
    extraction_missing_fields: missingFields.length > 0 ? missingFields : null
  }
};

// Get PDF text from the previous node
const pdfText = $input.first().json.text;

// Defensive: if text is empty, return a sentinel so downstream handles it
if (!pdfText || String(pdfText).trim() === '') {
  return {
    json: {
      body_string: JSON.stringify({
        error: 'empty_pdf_text',
        message: 'Extract from PDF returned empty text. PDF may be scanned or image-only.'
      })
    }
  };
}

// Build the full Groq request body as an object
const body = {
  model: 'openai/gpt-oss-20b',
  messages: [
    {
      role: 'system',
      content: 'You extract structured fields from invoice text. Return ONLY valid JSON matching the requested schema. If a field is not present in the text, use null. Do not invent values. Do not add explanation outside the JSON.'
    },
    {
      role: 'user',
      content: `Extract these fields from the invoice text below and return them as JSON:

- vendor_name (string)
- invoice_number (string)
- amount (number, without currency symbols or thousands separators)
- currency (string, 3-letter ISO code like USD, PHP, EUR)
- invoice_date (string, ISO format YYYY-MM-DD)
- due_date (string, ISO format YYYY-MM-DD)
- line_items_summary (string, one sentence summarizing what was billed)

Return this exact structure:
{
  "vendor_name": "...",
  "invoice_number": "...",
  "amount": 0.00,
  "currency": "...",
  "invoice_date": "YYYY-MM-DD",
  "due_date": "YYYY-MM-DD",
  "line_items_summary": "..."
}

Invoice text:
${pdfText}`
    }
  ],
  response_format: { type: 'json_object' },
  temperature: 0
};

// Return as a single string, ready for the HTTP Request node
return {
  json: {
    body_string: JSON.stringify(body)
  }
};

// Pull upstream data
// Look Up Vendor output is either [{vendor fields}] or [{}]
const vendor = $input.first().json;
const invoice = $('Parse Invoice Fields').first().json;

const reasons = [];

// ---------- INVALID checks ----------
let isInvalid = false;

const vendorFound = vendor.id != null;
if (!vendorFound) {
  reasons.push('Vendor not found in database');
  isInvalid = true;
}

if (vendorFound && vendor.is_active === false) {
  reasons.push('Vendor exists but is inactive');
  isInvalid = true;
}

if (invoice.amount == null || typeof invoice.amount !== 'number' || invoice.amount <= 0) {
  reasons.push('Amount is missing, non-numeric, or not positive');
  isInvalid = true;
}

if (!invoice.currency || typeof invoice.currency !== 'string' || invoice.currency.length !== 3) {
  reasons.push('Currency is missing or not a 3-letter code');
  isInvalid = true;
}

if (!invoice.invoice_date) {
  reasons.push('Invoice date is missing');
  isInvalid = true;
}

if (!invoice.due_date) {
  reasons.push('Due date is missing');
  isInvalid = true;
}

// If invalid, short-circuit. Don't also flag suspicious reasons.
let status = 'valid';
if (isInvalid) {
  status = 'invalid';
} else {
  // ---------- SUSPICIOUS checks ----------
  const invoiceDate = new Date(invoice.invoice_date);
  const dueDate = new Date(invoice.due_date);
  const today = new Date();

  if (invoice.amount > 100000) {
    reasons.push(`Amount exceeds threshold (${invoice.amount} > 100000)`);
  }

  if (dueDate < invoiceDate) {
    reasons.push('Due date is earlier than invoice date');
  }

  if (invoice.currency !== 'PHP') {
    reasons.push(`Non-PHP currency (${invoice.currency}) requires manual review`);
  }

  if (invoiceDate > today) {
    reasons.push('Invoice date is in the future');
  }

  if (reasons.length > 0) {
    status = 'suspicious';
  }
}

// If status is still valid and no reasons accumulated, note that for audit
if (status === 'valid' && reasons.length === 0) {
  reasons.push('All validation checks passed');
}

return {
  json: {
    // Pass through vendor info
    vendor_id: vendor.id || null,
    vendor_name: vendor.name || invoice.vendor_name,
    is_active: vendor.is_active || null,

    // Pass through invoice fields
    invoice_number: invoice.invoice_number,
    amount: invoice.amount,
    currency: invoice.currency,
    invoice_date: invoice.invoice_date,
    due_date: invoice.due_date,
    line_items_summary: invoice.line_items_summary,
    extraction_missing_fields: invoice.extraction_missing_fields,

    // Validation output
    status: status,
    status_reasons: reasons
  }
};

