// Helper: escape strings and handle nulls for SQL
const esc = (v) => {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
};

// Helper: handle numeric nulls
const num = (v) => (v === null || v === undefined ? 'NULL' : v);

// Pull the input item — preserves all fields from Compute Validation Status
const input = $input.first().json;

// Build the SQL string with proper NULLs
const sql = `
INSERT INTO invoices (
  vendor_id, vendor_name, invoice_number, amount, currency,
  invoice_date, due_date, line_items_summary, status, status_reasons, source_chat_id
)
VALUES (
  ${num(input.vendor_id)},
  ${esc(input.vendor_name)},
  ${esc(input.invoice_number)},
  ${num(input.amount)},
  ${esc(input.currency)},
  ${esc(input.invoice_date)},
  ${esc(input.due_date)},
  ${esc(input.line_items_summary)},
  ${esc(input.status)},
  ARRAY[${input.status_reasons.map(r => esc(r)).join(',')}]::text[],
  ${esc($('Telegram Trigger').first().json.message.chat.id)}
);
`;

return {
  json: {
    ...input,
    sqlQuery: sql
  }
};
